<?php require 'config/database.php';$pageTitle='Application';$selectedJob=(string)($_GET['job']??'');$jobs=$conn->query('SELECT job_id,title FROM jobs ORDER BY title');include 'includes/header.php';?>
<form class="card application-card" method="post" action="save_application.php" enctype="multipart/form-data"><h1>Job Application</h1><?php if(isset($_GET['error'])):?><div class="error"><?=htmlspecialchars($_GET['error'])?></div><?php endif;?><div class="form-intro"><b>Start your career journey</b><span>After submitting, save your Application ID to check whether you are Selected, Rejected or still under review.</span></div><div class="grid"><label>Full name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="6" required></label><label>Phone<input name="phone" required></label><label>Qualification<input name="qualification" required></label><label>Address<input name="address" required></label><label class="full">Skills<input name="skills" required></label><label>Job<select name="job_id" required><option value="">Select a position</option><?php while($job=$jobs->fetch_assoc()):?><option value="<?=$job['job_id']?>" <?=$selectedJob===$job['job_id']?'selected':''?>><?=htmlspecialchars($job['title'])?></option><?php endwhile;?></select></label><label>Résumé (PDF, DOC, JPG, PNG)<input type="file" name="resume" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,image/jpeg,image/png" required><small class="field-help">Maximum 5 MB · Clear JPG/JPEG/PNG images are accepted</small></label><label class="full">Cover letter<textarea name="cover_letter" rows="5" required></textarea></label></div><button class="submit">Submit & Get Application ID →</button></form><?php include 'includes/footer.php';?>
